// Определяем базовый URL API в зависимости от окружения
const getApiBaseUrl = () => {
  // Проверяем, находимся ли мы в Telegram WebApp
  const isTelegramWebApp = window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1';
  
  if (isTelegramWebApp) {
    // В Telegram WebApp используем относительный путь
    return import.meta.env.VITE_API_URL || '';
  }
  
  // Для локальной разработки
  return import.meta.env.VITE_API_URL || 'http://localhost:4000';
};

// Проверяем доступность API
const isApiAvailable = () => {
  const baseUrl = getApiBaseUrl();
  // Если нет базового URL, значит API недоступен
  return baseUrl !== '';
};

export interface UserData {
  id: string;
  telegramId: string;
  username?: string;
  firstName?: string;
  lastName?: string;
  currentDay: number;
  currentStep: string;
  progress: {
    day1: boolean;
    day2: boolean;
    day3: boolean;
    day4: boolean;
  };
  journal: any[];
  deck: {
    selectedCards: any[];
    completedReadings: number;
  };
  timers: Record<string, any>;
  createdAt: string;
  updatedAt: string;
}

export class UserApi {
  private static debounceTimers: Map<string, NodeJS.Timeout> = new Map();

  private static debounce(key: string, fn: () => void, delay: number = 1000): void {
    // Очищаем предыдущий таймер
    const existingTimer = this.debounceTimers.get(key);
    if (existingTimer) {
      clearTimeout(existingTimer);
    }

    // Устанавливаем новый таймер
    const timer = setTimeout(() => {
      fn();
      this.debounceTimers.delete(key);
    }, delay);

    this.debounceTimers.set(key, timer);
  }

  private static getUserId(): string | null {
    // Получаем ID пользователя из Telegram WebApp
    if (window.Telegram?.WebApp?.initDataUnsafe?.user?.id) {
      return window.Telegram.WebApp.initDataUnsafe.user.id.toString();
    }
    
    // Fallback только для локальной разработки (не в продакшене)
    const isProduction = window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1';
    if (!isProduction) {
      let userId = localStorage.getItem('shadow_quest_user_id');
      if (!userId) {
        userId = `dev_user_${Date.now()}`;
        localStorage.setItem('shadow_quest_user_id', userId);
      }
      return userId;
    }
    
    // В продакшене без Telegram WebApp - ждем инициализации или возвращаем null
    console.warn('Telegram WebApp не инициализирован, пропускаем API вызов');
    return null;
  }

  /**
   * Создает или обновляет пользователя в базе данных
   */
  static async createOrUpdateUser(): Promise<UserData | null> {
    try {
      // Проверяем доступность API
      if (!isApiAvailable()) {
        console.log('API not available, skipping user creation');
        return null;
      }
      
      const userId = this.getUserId();
      
      // Если userId null, значит Telegram WebApp не инициализирован
      if (!userId) {
        console.log('Skipping user creation - Telegram WebApp not initialized');
        return null;
      }
      
      // Получаем данные пользователя из Telegram
      const telegramUser = window.Telegram?.WebApp?.initDataUnsafe?.user;
      
      const response = await fetch(`${getApiBaseUrl()}/api/users`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          telegramId: telegramUser?.id?.toString() || userId,
          username: telegramUser?.username,
          firstName: telegramUser?.first_name,
          lastName: telegramUser?.last_name
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to create/update user: ${response.statusText}`);
      }

      const user = await response.json();
      console.log('User created/updated successfully:', user);
      return user;
    } catch (error) {
      console.error('Error creating/updating user:', error);
      return null;
    }
  }

  /**
   * Получает данные пользователя из базы данных
   */
  static async getUser(): Promise<UserData | null> {
    try {
      // Проверяем доступность API
      if (!isApiAvailable()) {
        console.log('API not available, skipping user loading');
        return null;
      }
      
      const userId = this.getUserId();
      
      // Если userId null, значит Telegram WebApp не инициализирован
      if (!userId) {
        console.log('Skipping user loading - Telegram WebApp not initialized');
        return null;
      }
      
      const response = await fetch(`${getApiBaseUrl()}/api/users/${userId}`);

      if (!response.ok) {
        if (response.status === 404) {
          return null; // Пользователь не найден
        }
        throw new Error(`Failed to get user: ${response.statusText}`);
      }

      const user = await response.json();
      console.log('User loaded:', user);
      return user;
    } catch (error) {
      console.error('Error loading user:', error);
      return null;
    }
  }

  /**
   * Обновляет прогресс пользователя
   */
  static async updateProgress(progress: Partial<UserData>): Promise<UserData | null> {
    try {
      // Проверяем доступность API
      if (!isApiAvailable()) {
        console.log('API not available, skipping progress update');
        return null;
      }
      
      const userId = this.getUserId();
      
      // Если userId null, значит Telegram WebApp не инициализирован
      if (!userId) {
        console.log('Skipping progress update - Telegram WebApp not initialized');
        return null;
      }
      
      const response = await fetch(`${getApiBaseUrl()}/api/users/${userId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(progress)
      });

      if (!response.ok) {
        throw new Error(`Failed to update progress: ${response.statusText}`);
      }

      const user = await response.json();
      console.log('Progress updated:', user);
      return user;
    } catch (error) {
      console.error('Error updating progress:', error);
      return null;
    }
  }

  /**
   * Сохраняет текущий шаг пользователя
   */
  static async saveCurrentStep(step: string): Promise<void> {
    const userId = this.getUserId();
    if (!userId) {
      console.log('Skipping saveCurrentStep - Telegram WebApp not initialized');
      return;
    }

    // Используем debouncing для предотвращения слишком частых запросов
    this.debounce(`saveCurrentStep_${userId}`, async () => {
      try {
        await this.updateProgress({ currentStep: step });
      } catch (error) {
        console.error('Error saving current step:', error);
      }
    }, 500); // 500ms задержка
  }

  /**
   * Сохраняет текущий день пользователя
   */
  static async saveCurrentDay(day: number): Promise<void> {
    const userId = this.getUserId();
    if (!userId) {
      console.log('Skipping saveCurrentDay - Telegram WebApp not initialized');
      return;
    }

    // Используем debouncing для предотвращения слишком частых запросов
    this.debounce(`saveCurrentDay_${userId}`, async () => {
      try {
        await this.updateProgress({ currentDay: day });
      } catch (error) {
        console.error('Error saving current day:', error);
      }
    }, 500); // 500ms задержка
  }

  /**
   * Отмечает день как завершенный
   */
  static async markDayCompleted(day: number): Promise<void> {
    try {
      const user = await this.getUser();
      if (!user) return;

      const progress = { ...user.progress };
      progress[`day${day}` as keyof typeof progress] = true;

      await this.updateProgress({ progress });
    } catch (error) {
      console.error('Error marking day as completed:', error);
    }
  }
}
